referenceSolutions.javascript:
export function solve(descriptor) {
  if (descriptor.override) return { ...descriptor.override };
  return descriptor.error !== null
    ? { status: "rejected", value: descriptor.error }
    : { status: "fulfilled", value: descriptor.values.length ? descriptor.values[0] : null };
}

